// Custom hook for typing placeholder animation
function useTypingPlaceholder(phrases, typingSpeed = 150, deletingSpeed = 75, pauseTime = 2000) {
  var [text, setText] = useState(() => phrases && phrases.length > 0 ? phrases[0].replace(/\.\.\.$/, '') : '');
  var [phraseIndex, setPhraseIndex] = useState(0);
  var [isDeleting, setIsDeleting] = useState(false);
  var [showCursor, setShowCursor] = useState(true);

  // Blinking cursor effect
  useEffect(() => {
    var cursorInterval = setInterval(() => {
      setShowCursor(prev => !prev);
    }, 530);
    return () => clearInterval(cursorInterval);
  }, []);

  // If phrases change (e.g. language change), reset state
  useEffect(() => {
    setText(phrases && phrases.length > 0 ? phrases[0].replace(/\.\.\.$/, '') : '');
    setPhraseIndex(0);
    setIsDeleting(false);
  }, [phrases]);
  useEffect(() => {
    if (!phrases || phrases.length === 0) return;
    var timeout;
    var currentIdx = phraseIndex % phrases.length;
    var currentPhrase = phrases[currentIdx];
    if (isDeleting) {
      if (text.length > 0) {
        timeout = setTimeout(() => {
          setText(prev => prev.slice(0, -1));
        }, deletingSpeed);
      } else {
        setIsDeleting(false);
        setPhraseIndex(prev => (prev + 1) % phrases.length);
      }
    } else {
      if (text.length < currentPhrase.length) {
        // First phrase '...' should animate slower
        var isTypingDots = currentIdx === 0 && text.length >= currentPhrase.replace(/\.\.\.$/, '').length;

        // Normal CPM rate (e.g. 200-300 CPM) involves varying delays per keystroke
        var baseSpeed = isTypingDots ? 400 : typingSpeed;
        var randomJitter = Math.random() * (baseSpeed * 0.5);
        var currentTypingSpeed = baseSpeed + randomJitter - baseSpeed * 0.25;
        timeout = setTimeout(() => {
          setText(currentPhrase.slice(0, text.length + 1));
        }, currentTypingSpeed);

        // Force cursor visible while typing for better UX
        setShowCursor(true);
      } else {
        timeout = setTimeout(() => {
          setIsDeleting(true);
        }, pauseTime);
      }
    }
    return () => clearTimeout(timeout);
  }, [text, isDeleting, phraseIndex, phrases, typingSpeed, deletingSpeed, pauseTime]);

  // Return a space to keep vertical height uniform when empty, avoiding layout jumps
  // Append a blinking cursor to enhance the typing effect
  return text + (showCursor ? '|' : '\u200A');
}

// Custom hook / component for Animated Rolling Numbers
function AnimatedNumber({
  value,
  formatFn = v => v,
  duration = 1200,
  delay = 0
}) {
  var [displayValue, setDisplayValue] = useState(value); // Start at target initially to prevent jarring jump if no animation happens
  var prevValueRef = useRef(0);
  var isInitialMount = useRef(true);
  useEffect(() => {
    var startTime = null;
    var animationFrame;
    var startValue = prevValueRef.current;
    var endValue = value;
    var valueDiff = endValue - startValue;

    // If it's pure 0 diff, no need to animate if not initial mount
    if (valueDiff === 0 && !isInitialMount.current) {
      return;
    }

    // Quick delay before starting
    var timeout = setTimeout(() => {
      var animate = currentTime => {
        if (!startTime) startTime = currentTime;
        var progress = Math.min((currentTime - startTime) / duration, 1);

        // easeOutExpo for realistic rolling slowdown
        var easeProgress = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
        setDisplayValue(startValue + valueDiff * easeProgress);
        if (progress < 1) {
          animationFrame = requestAnimationFrame(animate);
        } else {
          prevValueRef.current = endValue; // Save for next animation
        }
      };
      animationFrame = requestAnimationFrame(animate);
    }, isInitialMount.current ? delay : 0);
    isInitialMount.current = false;
    return () => {
      clearTimeout(timeout);
      cancelAnimationFrame(animationFrame);
    };
  }, [value, duration, delay]);
  return React.createElement(React.Fragment, null, formatFn(displayValue));
}

// APY sanity constants
var APY_SANITY_LIMIT = 1000;
var DEFAULT_MIN_TVL = 100000; // $100K default floor

// Shape gate for a `?pool=` id before it is ever reflected into a fetch path
// (spec 216) — the SAME shape check generate-pool-pages.js's UUID_RE uses to
// decide which deep-linked ids are worth resolving a paint artifact for. A
// hostile/legacy `?pool=` value that doesn't look like a real DefiLlama pool
// id can never reach a `/pools/<id>.json` fetch.
var POOL_ARTIFACT_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// A pool with (near-)zero total APY is a no-supply-yield / collateral asset —
// it must never top the default browse (092). Below 0.01% reads as "0.00%"
// once formatApy rounds to 2 decimals — the exact population the UX audit flags.
var NO_SUPPLY_YIELD_EPSILON = 0.01;
var hasNoSupplyYield = pool => (pool.apyBase || 0) + (pool.apyReward || 0) < NO_SUPPLY_YIELD_EPSILON;

// Stablecoin symbol allowlist — mirrors planner.js's STABLE_SYMBOLS/isStableSymbol
// exactly. Duplicated rather than imported: this repo has no build step or module
// system linking app.js and planner.js, so each browser script is self-contained
// (see formatUsd/formatNum/formatApy below, which follow the same convention).
var STABLE_SYMBOLS = ['USDC', 'USDT', 'DAI', 'USDS', 'FRAX', 'TUSD', 'USDP', 'GUSD', 'LUSD', 'USDD', 'PYUSD', 'USDE', 'SUSD', 'CRVUSD', 'GHO', 'USD0', 'FDUSD', 'USDB', 'BUSD', 'MIM', 'DOLA', 'USDX', 'EURC', 'EURS', 'RLUSD', 'USDL', 'DEUSD', 'SDAI'];
var isStableSymbol = symbol => {
  if (!symbol) return false;
  var parts = String(symbol).toUpperCase().split(/[-_\/\s+]/).map(s => s.trim()).filter(Boolean);
  if (parts.length === 0) return false;
  return parts.every(p => STABLE_SYMBOLS.indexOf(p) !== -1);
};

// Token ⇄ pool-symbol matcher for the analytics search (token filter + the
// chain / protocol / pool-type counts that must agree with the grid).
// DefiLlama's pool `symbol` is frequently a VAULT ticker that embeds the base
// asset (STEAKUSDC, GTUSDCP, mwUSDC, ETHENAUSDC), so the old exact split-part
// equality (`symbol === 'USDC'`) silently dropped the largest venues — e.g.
// every Morpho Blue USDC vault on Base. Match on substring instead, mirroring
// DefiLlama's own token grouping. Trust rails stay orthogonal: the
// DEFAULT_MIN_TVL floor and APY sanity / anomaly demotion still apply to every
// matched pool downstream, so this widens coverage without weakening them.
var symbolMatchesToken = (poolSymbol, token) => {
  if (!poolSymbol || !token) return false;
  return String(poolSymbol).toUpperCase().includes(String(token).toUpperCase());
};

